// ZCL Structs

// Struct for  block threshold
typedef struct {
  zb_uint8_t blockThreshold;
  zb_uint8_t priceControl;
  zb_uint32_t blockPeriodStartTime;
  zb_uint32_t blockPeriodDurationMinutes;
  zb_uint8_t fuelType;
  zb_uint32_t standingCharge;
} tr_block_threshold_t;

// Struct for  block threshold sub payload
typedef struct {
  zb_uint8_t tierNumberOfBlockThresholds;
  zb_uint8_t * blockThreshold;
} tr_block_threshold_sub_payload_t;

// Struct for  chat participant
typedef struct {
  zb_uint16_t uid;
  zb_uint8_t * nickname;
} tr_chat_participant_t;

// Struct for  chat room
typedef struct {
  zb_uint16_t cid;
  zb_uint8_t * name;
} tr_chat_room_t;

// Struct for  configure reporting record
typedef struct {
  zb_uint8_t direction;
  zb_uint16_t attributeId;
  zb_uint8_t attributeType;
  zb_uint16_t minimumReportingInterval;
  zb_uint16_t maximumReportingInterval;
  zb_uint8_t * reportableChangeLocation;
  zb_uint16_t timeoutPeriod;
} tr_configure_reporting_record_t;

// Struct for  configure reporting status record
typedef struct {
  tr_status_t status;
  zb_uint8_t direction;
  zb_uint16_t attributeId;
} tr_configure_reporting_status_record_t;

// Struct for  debt payload
typedef struct {
  zb_uint32_t collectionTime;
  zb_uint32_t amountCollected;
  tr_repayment_debt_type_t debtType;
  zb_uint32_t outstandingDebt;
} tr_debt_payload_t;

// Struct for  device information record
typedef struct {
  zb_ieee_addr_t ieeeAddress;
  zb_uint8_t endpointId;
  zb_uint16_t profileId;
  zb_uint16_t deviceId;
  zb_uint8_t version;
  zb_uint8_t groupIdCount;
  tr_device_information_record_sort_t sort;
} tr_device_information_record_t;

// Struct for  discover attributes info record
typedef struct {
  zb_uint16_t attributeId;
  zb_uint8_t attributeType;
} tr_discover_attributes_info_record_t;

// Struct for  endpoint information record
typedef struct {
  zb_uint16_t networkAddress;
  zb_uint8_t endpointId;
  zb_uint16_t profileId;
  zb_uint16_t deviceId;
  zb_uint8_t version;
} tr_endpoint_information_record_t;

